const PREFIJO_RESPUESTAS = 'lab/g1/res/';
const TIPOS = ['dispensado', 'omitido', 'alarma', 'error'];
const mensaje = $json.message && typeof $json.message === 'object' ? $json.message : {};
const datos = mensaje.data && typeof mensaje.data === 'object' ? mensaje.data : {};
const errores = [];

const textoValido = (valor, max) => typeof valor === 'string' && valor.trim() !== '' && valor.length <= max;

const correlationId = textoValido(mensaje.correlation_id, 100) ? mensaje.correlation_id : null;
if (!correlationId) errores.push('correlation_id es obligatorio');

let replyTo = mensaje.reply_to;
const replyToValido = textoValido(replyTo, 200)
  && replyTo.startsWith(PREFIJO_RESPUESTAS)
  && !/[+#]/.test(replyTo);
if (!replyToValido) {
  errores.push('reply_to debe comenzar con ' + PREFIJO_RESPUESTAS);
  replyTo = PREFIJO_RESPUESTAS + 'errores/' + (correlationId ?? 'sin-id');
}

if (!textoValido(datos.dispositivo, 50)) errores.push('data.dispositivo es obligatorio (texto de hasta 50 caracteres)');
if (!TIPOS.includes(datos.tipo_evento)) errores.push('data.tipo_evento debe ser uno de: ' + TIPOS.join(', '));
if (datos.detalle !== undefined && datos.detalle !== null && (typeof datos.detalle !== 'string' || datos.detalle.length > 200)) errores.push('data.detalle debe ser texto de hasta 200 caracteres');
const cantidad = datos.cantidad === undefined ? 1 : datos.cantidad;
if (!Number.isInteger(cantidad) || cantidad <= 0) errores.push('data.cantidad debe ser un entero mayor a 0');

return {
  json: {
    valido: errores.length === 0,
    errores,
    correlation_id: correlationId,
    reply_to: replyTo,
    dispositivo: datos.dispositivo,
    tipo_evento: datos.tipo_evento,
    detalle: datos.detalle ?? null,
    cantidad,
  },
};

const validado = $('Validar solicitud').item.json;
return {
  json: {
    topic: validado.reply_to,
    payload: {
      ok: true,
      correlation_id: validado.correlation_id,
      result: { id: $json.id, status: 'created' },
    },
  },
};

return {
  json: {
    topic: $json.reply_to,
    payload: {
      ok: false,
      correlation_id: $json.correlation_id,
      errors: $json.errores,
    },
  },
};
